import 'dart:async';
import 'package:flutter/material.dart';
import 'editorial_api.dart';
import 'content_detail_page.dart';
import 'studio_widgets.dart';

class ContentListPage extends StatefulWidget{
  final EditorialApi api;final String? presetState;const ContentListPage({super.key,required this.api,this.presetState});
  @override State<ContentListPage> createState()=>_ContentListPageState();
}
class _ContentListPageState extends State<ContentListPage>{
  final search=TextEditingController();String? state,kind,risk;int offset=0;static const limit=40;Timer? debounce;late Future<Map<String,dynamic>> future;
  @override void initState(){super.initState();state=widget.presetState;future=_load();}
  @override void didUpdateWidget(covariant ContentListPage old){super.didUpdateWidget(old);if(old.presetState!=widget.presetState){state=widget.presetState;offset=0;_reload();}}
  @override void dispose(){search.dispose();debounce?.cancel();super.dispose();}
  Future<Map<String,dynamic>> _load()=>widget.api.searchItems(query:search.text,state:state,kind:kind,risk:risk,offset:offset,limit:limit);
  void _reload()=>setState(()=>future=_load());
  void _onSearch(String _){debounce?.cancel();debounce=Timer(const Duration(milliseconds:320),(){offset=0;_reload();});}
  @override Widget build(BuildContext context)=>Column(children:[
    Material(color:Theme.of(context).colorScheme.surface,child:Padding(padding:const EdgeInsets.fromLTRB(20,16,20,12),child:Column(children:[
      Row(children:[Expanded(child:TextField(controller:search,onChanged:_onSearch,decoration:InputDecoration(prefixIcon:const Icon(Icons.search),hintText:'Rechercher un cours, une évaluation, un programme…',suffixIcon:search.text.isEmpty?null:IconButton(onPressed:(){search.clear();offset=0;_reload();},icon:const Icon(Icons.close))))),const SizedBox(width:12),FilledButton.icon(onPressed:()=>_openCreate(context),icon:const Icon(Icons.add),label:const Text('Nouveau'))]),
      const SizedBox(height:12),SingleChildScrollView(scrollDirection:Axis.horizontal,child:Row(children:[
        _Filter(label:'État',value:state,items:const {'draft':'Brouillon','in_review':'À relire','changes_requested':'Corrections','approved':'Approuvé','published':'Publié','archived':'Archivé'},onChanged:(v){state=v;offset=0;_reload();}),
        _Filter(label:'Type',value:kind,items:const {'course':'Cours','assessment':'Évaluation','question_set':'Banque de questions','summary':'Résumé','flashcards':'Flashcards','solution':'Solution','audio_script':'Script audio'},onChanged:(v){kind=v;offset=0;_reload();}),
        _Filter(label:'Risque',value:risk,items:const {'standard':'Standard','medical':'Médical','high_stakes':'Enjeu élevé'},onChanged:(v){risk=v;offset=0;_reload();}),
        if(state!=null||kind!=null||risk!=null)TextButton.icon(onPressed:(){state=widget.presetState;kind=null;risk=null;offset=0;_reload();},icon:const Icon(Icons.filter_alt_off),label:const Text('Réinitialiser')),
      ])),
    ]))),
    Expanded(child:FutureBuilder<Map<String,dynamic>>(future:future,builder:(context,s){
      if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());
      if(s.hasError)return StudioErrorState(onRetry:_reload,message:s.error.toString());
      final data=s.data!;final items=(data['items'] as List<dynamic>? ?? const []);final total=(data['total']??0) as int;
      if(items.isEmpty)return StudioEmptyState(icon:Icons.inventory_2_outlined,title:'Aucun contenu',message:'Modifie tes filtres ou crée le premier contenu éditorial.',action:FilledButton.icon(onPressed:()=>_openCreate(context),icon:const Icon(Icons.add),label:const Text('Créer un contenu')));
      return Column(children:[
        Padding(padding:const EdgeInsets.symmetric(horizontal:20,vertical:8),child:Row(children:[Text('$total résultat${total>1?'s':''}',style:Theme.of(context).textTheme.labelLarge),const Spacer(),Text('Page ${offset~/limit+1}',style:Theme.of(context).textTheme.bodySmall)])),
        Expanded(child:ListView.separated(padding:const EdgeInsets.fromLTRB(20,4,20,24),itemCount:items.length,separatorBuilder:(_,__)=>const SizedBox(height:9),itemBuilder:(context,i){final x=items[i] as Map<String,dynamic>;return _ContentCard(item:x,onTap:()async{await Navigator.of(context).push(MaterialPageRoute(builder:(_)=>ContentDetailPage(api:widget.api,itemId:x['id'] as String)));_reload();});})),
        SafeArea(top:false,child:Padding(padding:const EdgeInsets.fromLTRB(20,8,20,14),child:Row(children:[OutlinedButton.icon(onPressed:offset<=0?null:(){offset=(offset-limit).clamp(0,1<<30).toInt();_reload();},icon:const Icon(Icons.chevron_left),label:const Text('Précédent')),const Spacer(),FilledButton.icon(onPressed:offset+limit>=total?null:(){offset+=limit;_reload();},icon:const Icon(Icons.chevron_right),label:const Text('Suivant'))]))),
      ]);
    }))
  ]);
  Future<void> _openCreate(BuildContext context)async{
    final result=await showDialog<Map<String,dynamic>>(context:context,builder:(_)=>const _CreateItemDialog());if(result==null)return;
    try{final item=await widget.api.createItem(result);if(!mounted)return;await Navigator.of(context).push(MaterialPageRoute(builder:(_)=>ContentDetailPage(api:widget.api,itemId:item['id'] as String)));_reload();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Création impossible : $e')));}
  }
}

class _ContentCard extends StatelessWidget{final Map<String,dynamic> item;final VoidCallback onTap;const _ContentCard({required this.item,required this.onTap});@override Widget build(BuildContext c){final state=item['state']?.toString();final risk=item['risk']?.toString();return Card(clipBehavior:Clip.antiAlias,child:InkWell(onTap:onTap,child:Padding(padding:const EdgeInsets.all(17),child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[Container(width:46,height:46,decoration:BoxDecoration(color:Theme.of(c).colorScheme.primaryContainer.withValues(alpha:.55),borderRadius:BorderRadius.circular(14)),child:Icon(item['kind']=='course'?Icons.menu_book_rounded:Icons.description_rounded)),const SizedBox(width:14),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(item['title']??'',style:Theme.of(c).textTheme.titleMedium?.copyWith(fontWeight:FontWeight.w800))),const SizedBox(width:8),StatusPill(prettyState(state),color:stateColor(c,state))]),const SizedBox(height:5),Text('${item['faculty_domain']} • ${item['program']} • ${item['level']}${item['semester']!=null?' • ${item['semester']}':''}',maxLines:1,overflow:TextOverflow.ellipsis),const SizedBox(height:9),Wrap(spacing:7,runSpacing:7,children:[StatusPill(prettyKind(item['kind']?.toString()),icon:Icons.category_outlined),StatusPill(prettyRisk(risk),color:risk=='medical'||risk=='high_stakes'?Colors.deepOrange:null),StatusPill(prettyRights(item['rights_status']?.toString()),color:item['rights_status']=='authorized'||item['rights_status']=='public_domain'?Colors.green:Colors.orange),Text('v${item['row_version']??1} • ${formatDate(item['updated_at'])}',style:Theme.of(c).textTheme.bodySmall)] )])),const SizedBox(width:8),const Icon(Icons.chevron_right)]))));}}

class _Filter extends StatelessWidget{final String label;final String? value;final Map<String,String> items;final ValueChanged<String?> onChanged;const _Filter({required this.label,required this.value,required this.items,required this.onChanged});@override Widget build(BuildContext c)=>Padding(padding:const EdgeInsets.only(right:9),child:DropdownButtonHideUnderline(child:DropdownButton<String>(value:value,hint:Text(label),borderRadius:BorderRadius.circular(16),items:[DropdownMenuItem(value:null,child:Text('Tous • $label')),for(final e in items.entries)DropdownMenuItem(value:e.key,child:Text(e.value))],onChanged:onChanged)));}

class _CreateItemDialog extends StatefulWidget{const _CreateItemDialog();@override State<_CreateItemDialog> createState()=>_CreateItemDialogState();}
class _CreateItemDialogState extends State<_CreateItemDialog>{final title=TextEditingController(),domain=TextEditingController(text:'Médecine'),program=TextEditingController(text:'Médecine humaine'),level=TextEditingController(text:'BAC1'),semester=TextEditingController(text:'S1'),rightsNote=TextEditingController();String kind='course',risk='standard',rights='unknown';
 @override void dispose(){for(final x in [title,domain,program,level,semester,rightsNote])x.dispose();super.dispose();}
 @override Widget build(BuildContext c)=>AlertDialog(title:const Text('Nouveau contenu'),content:SizedBox(width:580,child:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:title,autofocus:true,decoration:const InputDecoration(labelText:'Titre *')),const SizedBox(height:10),Row(children:[Expanded(child:DropdownButtonFormField(value:kind,decoration:const InputDecoration(labelText:'Type'),items:const[DropdownMenuItem(value:'course',child:Text('Cours')),DropdownMenuItem(value:'assessment',child:Text('Évaluation')),DropdownMenuItem(value:'question_set',child:Text('Banque de questions')),DropdownMenuItem(value:'summary',child:Text('Résumé')),DropdownMenuItem(value:'solution',child:Text('Solution'))],onChanged:(v)=>setState(()=>kind=v!))),const SizedBox(width:10),Expanded(child:DropdownButtonFormField(value:risk,decoration:const InputDecoration(labelText:'Risque'),items:const[DropdownMenuItem(value:'standard',child:Text('Standard')),DropdownMenuItem(value:'medical',child:Text('Médical')),DropdownMenuItem(value:'high_stakes',child:Text('Enjeu élevé'))],onChanged:(v)=>setState(()=>risk=v!)))]),const SizedBox(height:10),TextField(controller:domain,decoration:const InputDecoration(labelText:'Faculté / domaine *')),const SizedBox(height:10),TextField(controller:program,decoration:const InputDecoration(labelText:'Programme *')),const SizedBox(height:10),Row(children:[Expanded(child:TextField(controller:level,decoration:const InputDecoration(labelText:'Niveau *'))),const SizedBox(width:10),Expanded(child:TextField(controller:semester,decoration:const InputDecoration(labelText:'Semestre')))]),const SizedBox(height:10),DropdownButtonFormField(value:rights,decoration:const InputDecoration(labelText:'Droits de diffusion'),items:const[DropdownMenuItem(value:'unknown',child:Text('À vérifier')),DropdownMenuItem(value:'authorized',child:Text('Autorisé')),DropdownMenuItem(value:'public_domain',child:Text('Domaine public')),DropdownMenuItem(value:'internal_only',child:Text('Interne uniquement')),DropdownMenuItem(value:'restricted',child:Text('Restreint'))],onChanged:(v)=>setState(()=>rights=v!)),const SizedBox(height:10),TextField(controller:rightsNote,maxLines:2,decoration:const InputDecoration(labelText:'Note sur les droits'))]))),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Annuler')),FilledButton(onPressed:title.text.trim().isEmpty?null:()=>Navigator.pop(c,{'kind':kind,'title':title.text.trim(),'faculty_domain':domain.text.trim(),'program':program.text.trim(),'level':level.text.trim(),'semester':semester.text.trim().isEmpty?null:semester.text.trim(),'risk':risk,'rights_status':rights,'rights_note':rightsNote.text.trim(),'source_fingerprint':''}),child:const Text('Créer'))]);}
